SELECT SERVER_VERSION();
SHOW DNODES;
SHOW MNODES;

SHOW DATABASES;
USE <DBNAME>;
SHOW STABLES;
SHOW TABLES;

-- 1. 先看当前在跑的查询（只读）：
SHOW QUERIES;
-- 2. 对可疑 SQL 看执行计划（模板，替换为真实 SQL）：
EXPLAIN SELECT * FROM <STABLE> WHERE ts >= now - 1h;

SELECT LAST_ROW(*) FROM <STABLE>;
SELECT tbname, LAST_ROW(ts) AS last_ts, now - LAST_ROW(ts) AS lag
FROM <STABLE> PARTITION BY tbname ORDER BY lag DESC LIMIT 20;

SELECT db_name, data_size, storage_size,
  round(data_size * 1.0 / NULLIF(storage_size, 0), 2) AS compression_ratio
FROM information_schema.ins_databases ORDER BY storage_size DESC;

-- 1. 先确认当前参数（只读）：
SHOW CREATE DATABASE <DBNAME>;
-- 2. 确认后再执行（KEEP 须 >= 3 倍 DURATION，缩短 KEEP 会丢弃过期数据）：
-- DANGER: ALTER DATABASE <DBNAME> KEEP <KEEP> COMP <COMP>;

-- 1. 先查看备份记录（只读）：
SHOW BACKUPS;
-- 2. 全量备份（仅企业版，联机执行）：
-- DANGER: CREATE FULL BACKUP ON DNODE <DNODE_ID> TO '<BACKUP_PATH>';
-- 3. 恢复为离线危险操作，先在测试环境演练：
-- DANGER: taosd --restore <BACKUP_CHAIN_PATH> --verify=1

SHOW DNODES;
SHOW MNODES;
SHOW VGROUPS;
SHOW CREATE DATABASE <DBNAME>;

-- 1. 先查看现有用户（只读）：
SHOW USERS;
-- 2. 新建用户（模板）：
-- DANGER: CREATE USER <USERNAME> PASS '<PASSWORD>';
-- 3. 授权示例（语法按手册核对）：
